import { useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { doc, deleteDoc } from "firebase/firestore"; // Функции за Firestore
import { db } from "../../config/firebaseConfig"; // Импортиране на Firebase конфигурацията

export default function DeleteProject() {
    const navigate = useNavigate();
    const { projectId } = useParams(); // Получаваме projectId от URL параметъра

    useEffect(() => {
        const deleteProjectFromFirebase = async () => {
            try {
                // Създаване на референция към документа в Firestore
                const projectRef = doc(db, "projects", projectId);

                // Изтриване на документа
                await deleteDoc(projectRef);

                // Навигиране към страницата с проекти след успешно изтриване
                navigate('/projects');
            } catch (error) {
                console.error("Error deleting project:", error);
                alert("Неуспешно изтриване на проекта!"); // Показваме грешка, ако има проблем
            }
        };

        deleteProjectFromFirebase();
    }, [projectId, navigate]); // Следим промените на projectId и navigate

    return null; // Не показваме UI, тъй като процесът е автоматичен
}
